"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2768],{59401:e=>{e.exports=JSON.parse('{"functions":[{"name":"promptGameFavorite","desc":"Asks the player to favorite the game, then reports the result to the\\nserver.\\n\\nNo-ops when `playerData.claims[Awards.claimNameForFavoringGame]` is\\nalready set, so a player who has taken the reward is never prompted again.\\n\\nOtherwise it fires a top-positioned `bob` dialog through\\n[MessageController], waits 0.8s so the dialog is readable before the\\nRoblox prompt covers it, calls `AvatarEditorService:PromptSetFavorite` for\\n`GameData.livePlaceId`, and dispatches `MONETIZATION_FAVORITED_GAME` with\\n`didFavorite` once the prompt resolves.\\n\\n:::caution\\nYields \u2014 the `task.wait(0.8)` runs on the caller\'s thread. Call it from a\\nspawned thread, not from an input handler you want to return promptly.\\nThe result listener is a `:Once`, so a prompt the player dismisses without\\nresolving simply never reports.\\n:::","params":[],"returns":[],"function_type":"static","source":{"line":52,"path":"src/Client/Features/Core/Controllers/MonetizationController.luau"}}],"properties":[],"types":[],"name":"MonetizationController","desc":"Client-side monetization prompts. Today that is one flow: asking the\\nplayer to favorite the game in exchange for a coin reward.\\n\\nThe reward itself is granted server-side \u2014 this controller only drives the\\nRoblox prompt and reports the outcome. See `MonetizationService` for the\\n`MONETIZATION_FAVORITED_GAME` handler.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","realm":["Client"],"source":{"line":15,"path":"src/Client/Features/Core/Controllers/MonetizationController.luau"}}')}}]);